grid = [[9]*27 for _ in range(11)]
# frame 3 at rows 1..7, columns 14..20 (0-based)
for r in range(1,8):
    for c in range(14,21):
        if r in (1,7) or c in (14,20): grid[r][c]=3
# interior 5x5 filled with 7
for r in range(2,7):
    for c in range(15,20): grid[r][c]=7
# frame 0 at rows 2..7, cols 1..6; interior 4x4 filled 2
for r in range(2,8):
    for c in range(1,7):
        if r in (2,7) or c in (1,6): grid[r][c]=0
for r in range(3,7):
    for c in range(2,6): grid[r][c]=2
# frame 6 3x3 at rows 5..7, cols 9..11
for r in range(5,8):
    for c in range(9,12):
        if r in (5,7) or c in (9,11): grid[r][c]=6
# center single cell: odd-sized interior -> 7
grid[6][10]=7
assert len(grid)==11 and all(len(row)==27 for row in grid)
print(__import__('json').dumps(grid, separators=(',',':')))

